function cleanText(value) {
  const entities = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " " };
  return String(value ?? "")
    .replace(/<(?:script|style)\b[^>]*>[\s\S]*?<\/(?:script|style)>/gi, " ")
    .replace(/<[^>]*>/g, " ")
    .replace(/&(#(?:x[\da-f]+|\d+)|amp|lt|gt|quot|apos|nbsp);/gi, (entity, name) => {
      if (name[0] !== "#") return entities[name.toLowerCase()] ?? entity;
      const n = /^#x/i.test(name) ? Number.parseInt(name.slice(2), 16) : Number(name.slice(1));
      return n > 0 && n <= 0x10ffff && !(n >= 0xd800 && n <= 0xdfff)
        ? String.fromCodePoint(n)
        : entity;
    })
    .replace(/\s+/g, " ")
    .trim();
}

function publicUrl(value) {
  if (typeof value !== "string") return "";
  const match = value.match(
    /^https?:\/\/[a-z0-9][a-z0-9.-]*[a-z0-9](?::(\d{1,5}))?(?:[/?#][^\s"'<>\\]*)?$/i,
  );
  return match && (!match[1] || Number(match[1]) <= 65535) ? value : "";
}

function keyForArticle(uri, timestamp) {
  let hash = 2166136261;
  for (const ch of uri) hash = Math.imul(hash ^ ch.codePointAt(0), 16777619);
  hash >>>= 0;
  const micros = BigInt(timestamp) * 1000n + BigInt((hash >>> 10) % 1000);
  if (micros < 0n || micros >= 1n << 53n)
    throw new Error("RSS publication time falls outside the Bluesky record key range");
  let value = (micros << 10n) | BigInt(hash & 1023);
  let key = "";
  const alphabet = "234567abcdefghijklmnopqrstuvwxyz";
  for (let i = 0; i < 13; i++) {
    key = alphabet[Number(value & 31n)] + key;
    value >>= 5n;
  }
  return key;
}

function limitText(text, limit) {
  const segmenter = new Intl.Segmenter(undefined, { granularity: "grapheme" });
  let result = "",
    bytes = 0,
    count = 0;
  const utf8 = new TextEncoder();
  for (const { segment } of segmenter.segment(text)) {
    bytes += utf8.encode(segment).length;
    if (count++ === limit || bytes > 3000) break;
    result += segment;
  }
  return result.trimEnd();
}

function planArticle(item, override = "") {
  const uri = publicUrl(item.link);
  const title = cleanText(item.title);
  const description = cleanText(item.contentSnippet ?? item.description ?? item.content);
  const text = limitText(
    cleanText(item["content:encodedSnippet"] ?? item["content:encoded"]) || description || title,
    200,
  );
  const timestamp = Date.parse(item.isoDate ?? item.pubDate ?? item.published);
  const imageUrl = publicUrl(override || item.enclosure?.url);
  if (!uri || !title || !Number.isSafeInteger(timestamp) || timestamp < 0 || !imageUrl) {
    return {
      valid: false,
      uri,
      reason: "Expected a title, dated article link and a public image URL",
    };
  }
  const rkey = keyForArticle(uri, timestamp);
  return {
    valid: true,
    uri,
    title,
    description,
    text,
    timestamp,
    rkey,
    imageUrl,
    declaredMime: override ? "" : String(item.enclosure?.type ?? ""),
  };
}

const override = "";
const item = planArticle($json, override);
return { json: item };

function thumbnailType(input, reported = "", declared = "") {
  const bytes = new Uint8Array(input);
  if (bytes.length < 16 || bytes.length > 1_000_000) return null;
  const has = (at, prefix) => [...prefix].every((byte, i) => bytes[at + i] === byte);
  const data = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  let mime = null;
  if (
    bytes.length >= 45 &&
    has(0, [137, 80, 78, 71, 13, 10, 26, 10]) &&
    has(8, [0, 0, 0, 13, 73, 72, 68, 82]) &&
    data.getUint32(16) &&
    data.getUint32(20) &&
    has(bytes.length - 12, [0, 0, 0, 0, 73, 69, 78, 68])
  )
    mime = "image/png";
  else if (has(0, [255, 216, 255]) && has(bytes.length - 2, [255, 217])) mime = "image/jpeg";
  else if (
    (has(0, [71, 73, 70, 56, 55, 97]) || has(0, [71, 73, 70, 56, 57, 97])) &&
    data.getUint16(6, true) &&
    data.getUint16(8, true) &&
    bytes.at(-1) === 59
  )
    mime = "image/gif";
  else if (
    bytes.length >= 20 &&
    has(0, [82, 73, 70, 70]) &&
    data.getUint32(4, true) === bytes.length - 8 &&
    has(8, [87, 69, 66, 80, 86, 80, 56]) &&
    [32, 76, 88].includes(bytes[15])
  )
    mime = "image/webp";
  for (const raw of [reported, declared]) {
    const type = String(raw).split(";")[0].trim().toLowerCase().replace("image/jpg", "image/jpeg");
    if (type && type !== "application/octet-stream" && type !== mime) return null;
  }
  return mime;
}

const item = $input.first();
const { statusCode, headers } = item.json;
const article = $("Prepare this article").item.json;
if (statusCode !== 200 || !item.binary?.data)
  return [
    {
      json: {
        valid: false,
        article: article.uri,
        reason: "The enclosure returned HTTP " + statusCode,
      },
    },
  ];
const bytes = await this.helpers.getBinaryDataBuffer(0, "data");
const mime = thumbnailType(bytes, headers["content-type"], article.declaredMime);
if (!mime)
  return [
    { json: { valid: false, article: article.uri, reason: "Unsupported image content or size" } },
  ];
item.binary.data.mimeType = mime;
return [{ json: { valid: true, mime, size: bytes.length }, binary: item.binary }];

function checkedSession(body) {
  if (
    !/^did:[a-z0-9]+:[A-Za-z0-9._:%-]+$/.test(body?.did ?? "") ||
    typeof body?.accessJwt !== "string" ||
    !/^[A-Za-z0-9_.-]+$/.test(body.accessJwt)
  )
    throw new Error("Bluesky returned an invalid session");
  return { repo: body.did, token: body.accessJwt };
}

return { json: checkedSession($json) };

function assertPostReceipt(body, expectedUri) {
  if (
    body?.uri !== expectedUri ||
    typeof body.cid !== "string" ||
    !/^b[a-z2-7]{20,}$/.test(body.cid)
  ) {
    throw new Error("Bluesky did not confirm the expected post URI and CID");
  }
  return { uri: body.uri, cid: body.cid };
}

function findPost(status, body, item, expectedUri) {
  if ([400, 404].includes(status) && body?.error === "RecordNotFound") return null;
  if (status !== 200) throw new Error("Could not check the Bluesky record: HTTP " + status);
  const receipt = assertPostReceipt(body, expectedUri);
  const embed = body.value?.embed;
  if (
    body.value?.$type !== "app.bsky.feed.post" ||
    embed?.$type !== "app.bsky.embed.external" ||
    embed.external?.uri !== item.uri ||
    embed.external?.thumb?.$type !== "blob"
  )
    throw new Error("The Bluesky record key is occupied by a different post");
  return { status: "already_posted", ...receipt };
}

const article = $("Prepare this article").item.json;
const uri =
  "at://" +
  $("Validate the Bluesky session").item.json.repo +
  "/app.bsky.feed.post/" +
  article.rkey;
const previous = findPost($json.statusCode, $json.body, article, uri);
return { json: { create: !previous, receipt: previous, uri } };

function postWithThumbnail(item, did, body, mime, size, createdAt) {
  const thumb = body?.blob;
  if (
    thumb?.$type !== "blob" ||
    !/^b[a-z2-7]{20,}$/.test(thumb.ref?.$link ?? "") ||
    thumb.mimeType !== mime ||
    thumb.size !== size
  )
    throw new Error("Bluesky did not confirm the uploaded image bytes");
  return {
    repo: did,
    collection: "app.bsky.feed.post",
    rkey: item.rkey,
    validate: true,
    record: {
      $type: "app.bsky.feed.post",
      text: item.text,
      langs: ["es-ES"],
      createdAt,
      embed: {
        $type: "app.bsky.embed.external",
        external: { uri: item.uri, title: item.title, description: item.description, thumb },
      },
    },
  };
}

const { mime, size } = $("Validate the thumbnail bytes").item.json;
return {
  json: postWithThumbnail(
    $("Prepare this article").item.json,
    $("Validate the Bluesky session").item.json.repo,
    $json,
    mime,
    size,
    new Date().toISOString(),
  ),
};

function assertPostReceipt(body, expectedUri) {
  if (
    body?.uri !== expectedUri ||
    typeof body.cid !== "string" ||
    !/^b[a-z2-7]{20,}$/.test(body.cid)
  ) {
    throw new Error("Bluesky did not confirm the expected post URI and CID");
  }
  return { uri: body.uri, cid: body.cid };
}

const uri = $("Check whether the article was already posted").item.json.uri;
if ($json.statusCode < 200 || $json.statusCode >= 300)
  throw new Error("Bluesky creation was not confirmed. Check " + uri + " before trying again.");
return { json: { status: "posted", ...assertPostReceipt($json.body, uri) } };
